{
  "name": "Newport XPS SFTP文件交互组件",
  "name_en": "Newport XPS SFTP File Interaction Component",
  "manufacturer": "Newport",
  "description": "用于 Newport XPS 型号 D 控制器的非物理 SFTP 文件交互组件。它在实验系统中负责连接远程文件服务、切换目录、读取文本文件、上传内容、下载文件以及进行基础文件管理，常用于配置文件、脚本和日志的交换。",
  "description_en": "A non-physical SFTP file interaction component for Newport XPS model D controllers. It is used in lab systems to connect to the remote file service, change directories, read text files, upload content, download files, and perform basic file management, typically for exchanging configuration files, scripts, and logs.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到远程 XPS 文件服务。",
      "description_en": "Connect to the remote XPS file service."
    },
    {
      "action_name": "auto-cwd",
      "description": "切换远程工作目录。",
      "description_en": "Change the remote working directory."
    },
    {
      "action_name": "auto-getlines",
      "description": "读取远程文本文件内容。",
      "description_en": "Read the contents of a remote text file."
    },
    {
      "action_name": "auto-put",
      "description": "将文本内容上传到远程文件。",
      "description_en": "Upload text content to a remote file."
    },
    {
      "action_name": "auto-save",
      "description": "将远程文件保存到本地文件。",
      "description_en": "Save a remote file to a local file."
    },
    {
      "action_name": "auto-list",
      "description": "列出远程目录中的文件或条目。",
      "description_en": "List files or entries in the remote directory."
    },
    {
      "action_name": "auto-delete",
      "description": "删除远程文件或条目。",
      "description_en": "Delete a remote file or entry."
    }
  ],
  "tag_hints": [
    "Newport XPS",
    "SFTP file transfer",
    "remote file management",
    "configuration file exchange",
    "lab automation helper",
    "controller file access"
  ]
}

